const f = $input.first().json;
const now = new Date();
const defaultDate = now.toLocaleDateString('en-IN', { year:'numeric', month:'long', day:'numeric' });

return [{ json: {
  ...f,
  clientName: (f['Client Full Name'] || '').trim(),
  clientCompany: (f['Client Company Name'] || '').trim(),
  clientEmail: (f['Client Email'] || '').trim(),
  serviceRequired: (f['Service Required'] || '').trim(),
  clientRequirements: (f['Client Specific Requirements'] || '').trim(),
  budget: (f['Agreed Budget (INR)'] || '').trim(),
  startDate: (f['Desired Start Date'] || defaultDate).trim(),
  agencyName: (f['Your Agency Name'] || '').trim(),
  yourName: (f['Your Name'] || '').trim(),
  yourEmail: (f['Your Email'] || '').trim(),
  timestamp: now.toISOString()
}}];

// Merge client data with service database data
// FIX: Filter for the correct service row instead of blindly taking the first one
const allServices = $input.all().map(i => i.json);
const client = $('🔧 Parse Client Details').first().json;

// Find the matching service by name (case-insensitive)
const matchedRow = allServices.find(row => 
  (row['Service Name'] || '').trim().toLowerCase() === (client.serviceRequired || '').trim().toLowerCase()
) || allServices[0]; // Fallback to first row if no match

const service = {
  id: matchedRow['Service ID'] || '',
  name: matchedRow['Service Name'] || '',
  description: matchedRow['Description'] || '',
  deliverables: (matchedRow['Deliverables'] || '').split('|').map(d => d.trim()).filter(Boolean),
  sopSteps: (matchedRow['SOP Steps'] || '').split('|').map(s => s.trim()).filter(Boolean),
  defaultTimeline: matchedRow['Default Timeline'] || '2 Weeks',
  toolsUsed: matchedRow['Tools Used'] || '',
  priceRange: matchedRow['Price Range (INR)'] || '',
  prerequisites: matchedRow['Prerequisites From Client'] || ''
};

return [{ json: { ...client, service } }];

const aiResp = $('🤖 Gemini: Build Project Plan from SOPs').first().json;
const prev = $('🔀 Merge Client + Service Data').first().json;

let plan = {};
try {
  const raw = aiResp?.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  plan = JSON.parse(raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim());
} catch (e) {
  // Fallback using database data directly
  const s = prev.service;
  plan = {
    project_title: `${s.name} for ${prev.clientCompany}`,
    calculated_timeline: s.defaultTimeline,
    welcome_message: `Welcome to ${prev.agencyName}! We are excited to build your ${s.name} solution.`,
    project_summary: `We will ${s.description} for ${prev.clientCompany}. ${prev.clientRequirements}`,
    roadmap: [{ week: 'Week 1', phase: 'Discovery & Setup', tasks: s.sopSteps.slice(0,4), deliverables_due: s.deliverables.slice(0,3), milestone: 'Project kickoff complete' }],
    deliverables_with_dates: s.deliverables.map((d, i) => ({ name: d, description: d, due_week: `Week ${Math.ceil((i+1) / 3)}`, owner: 'Agency' })),
    sop_for_client: s.sopSteps.map((step, i) => ({ step: i+1, title: step, description: step, duration: '2-3 days', client_action_needed: 'None' })),
    prerequisites_checklist: s.prerequisites.split(' and ').map(p => p.trim()),
    communication_plan: { kickoff: 'Within 2 days', updates: 'Weekly on Monday', reviews: 'End of each phase', escalation: 'Email with URGENT in subject' },
    payment_schedule: [{ milestone: 'Project Start', percentage: '50%', amount: `INR ${Math.round(parseInt(prev.budget)/2)}`, due: 'Before kickoff' }, { milestone: 'Project Completion', percentage: '50%', amount: `INR ${Math.round(parseInt(prev.budget)/2)}`, due: 'On delivery' }],
    tools_access_needed: s.toolsUsed.split(' and ').map(t => t.trim()),
    success_metrics: ['Project delivered on time', 'All deliverables approved by client', 'Client satisfaction score above 8/10'],
    warranty_and_support: '14-day post-launch support included',
    next_immediate_step: 'Schedule kickoff call within 48 hours'
  };
}

return [{ json: { ...prev, plan } }];

// Expand deliverables into individual rows for tracking
const d = $input.first().json;
const deliverables = d.plan.deliverables_with_dates || [];
const client = `${d.clientName} (${d.clientCompany})`;

if (deliverables.length === 0) return [];

return deliverables.map(del => ({ json: {
  Client: client,
  Company: d.clientCompany,
  Email: d.clientEmail,
  Service: d.service.name,
  Deliverable: del.name || '',
  Description: del.description || '',
  'Due Date': del.due_week || '',
  Week: del.due_week || '',
  Owner: del.owner || 'Agency',
  Status: 'Not Started',
  'Client Approval': 'Pending',
  Notes: '',
  'Onboarded At': d.timestamp
} }));

// Global Config (cogdef) - Pulling from Environment Variables
const config = {
  safeMode: $env.SAFE_MODE === 'true',
  logDrainId: $env.LOG_DRAIN_ID || "FEK7PNwR6I3XZygD",
  spreadsheetId: $env.SPREADSHEET_ID || "16dAe64XCQ_iecfAlrrdG5n6TtJyr2cDrMmIN4Uv9xBU",
  env: $env.NODE_ENV || "production",
  roiMins: 120
};

return $input.all().map(item => ({
  json: { 
    ...item.json,
    ...config,
    cogdef: config 
  }
}));

// Prepare a master row for the Summary tab
// Column headers per Week10 Setup Guide: clientName, clientCompany, clientEmail, serviceRequired,
// clientRequirements, budget, agencyName, yourName, yourEmail, startDate, timestamp, service, plan
// CRITICAL: Must also include Status column so downstream workflows (Follow-Up, Check-In, Offboarding)
// can filter by Status value when reading from this tab.
const d = $input.first().json;
return [{ json: {
  clientName: d.clientName,
  clientCompany: d.clientCompany,
  clientEmail: d.clientEmail,
  serviceRequired: d.serviceRequired || d.service.name,
  clientRequirements: d.clientRequirements,
  budget: d.budget,
  agencyName: d.agencyName,
  yourName: d.yourName,
  yourEmail: d.yourEmail,
  startDate: d.startDate,
  timestamp: d.timestamp,
  Status: 'Welcome Email Sent',
  service: JSON.stringify(d.service),
  plan: JSON.stringify(d.plan)
} }];
